  const fit={roman:{scale:[.17,.195,.20],shift:[0,.011,-.050]},gladiator:{scale:[.95,.95,.95],shift:[0,-.133,-.008]},knights:{scale:[.028,.021,.025],shift:[0,.039,.024]},winged:{scale:[.0086,.0100,.0094],shift:[0,0,-.018]}}[key];
