   const merged=typeof ArenaGeometryUtils!=='undefined'&&geometries.length>1?ArenaGeometryUtils.mergeGeometries(geometries,false):null;
   for(const geometry of merged?[merged]:geometries){geometry.computeBoundingBox();geometry.computeBoundingSphere();const mesh=new T.Mesh(geometry,material);mesh.castShadow=mesh.receiveShadow=true;group.add(mesh);}
