   if(!ix||!wt)return;for(let i=0;i<o.geometry.attributes.position.count;i++){let weight=0;for(let k=0;k<4;k++)if(o.skeleton.bones[ix.getComponent(i,k)]?.name.includes('Head'))weight+=wt.getComponent(i,k);if(weight<.65)continue;o.getVertexPosition(i,p).applyMatrix4(o.matrixWorld);m.root.worldToLocal(p);bounds.expandByPoint(p);}
